export interface ClassifiedFace {
  index: number;
  id: string; // "BRepFace-${index}"
  type: "planar" | "cylindrical" | "curved";
  area: number;
  center: { x: number; y: number; z: number };
  normal?: { x: number; y: number; z: number };
  isInner: boolean;
}

/**
 * Parses triangle meshes generated by the Open Cascade tessellator
 * and classifies them geometrically into Planes, Cylinders, or Complex Curves.
 */
export function classifyBRepFaces(meshes: any[]): ClassifiedFace[] {
  if (!meshes) return [];

  return meshes.map((mesh, index) => {
    const positions = mesh.positions || [];
    const indices = mesh.indices || [];

    let totalArea = 0;
    let centerX = 0, centerY = 0, centerZ = 0;
    const vertexCount = positions.length / 3;

    // 1. Calculate the spatial centroid
    for (let i = 0; i < positions.length; i += 3) {
      centerX += positions[i];
      centerY += positions[i + 1];
      centerZ += positions[i + 2];
    }
    if (vertexCount > 0) {
      centerX /= vertexCount;
      centerY /= vertexCount;
      centerZ /= vertexCount;
    }

    // 2. Identify triangle normal variances and check radial orientation bias
    const uniqueNormals: [number, number, number][] = [];
    let dotSum = 0;
    let dotCount = 0;

    for (let i = 0; i < indices.length; i += 3) {
      const idx0 = indices[i] * 3;
      const idx1 = indices[i + 1] * 3;
      const idx2 = indices[i + 2] * 3;

      const x0 = positions[idx0], y0 = positions[idx0 + 1], z0 = positions[idx0 + 2];
      const x1 = positions[idx1], y1 = positions[idx1 + 1], z1 = positions[idx1 + 2];
      const x2 = positions[idx2], y2 = positions[idx2 + 1], z2 = positions[idx2 + 2];

      const ux = x1 - x0, uy = y1 - y0, uz = z1 - z0;
      const vx = x2 - x0, vy = y2 - y0, vz = z2 - z0;

      // Cross product
      const nx = uy * vz - uz * vy;
      const ny = uz * vx - ux * vz;
      const nz = ux * vy - uy * vx;

      const len = Math.sqrt(nx * nx + ny * ny + nz * nz);
      if (len > 1e-6) {
        const faceNormalNorm = [nx / len, ny / len, nz / len] as [number, number, number];
        totalArea += 0.5 * len;

        // Position of triangle center relative to face centroid
        const tcx = (x0 + x1 + x2) / 3 - centerX;
        const tcy = (y0 + y1 + y2) / 3 - centerY;
        const tcz = (z0 + z1 + z2) / 3 - centerZ;

        // Radial dot product (relative_vector . normal)
        // For outer boss/cylinders: normal points outward (dot > 0)
        // For inner holes/cylindres: normal points inward (dot < 0)
        const radialDot = tcx * faceNormalNorm[0] + tcy * faceNormalNorm[1] + tcz * faceNormalNorm[2];
        dotSum += radialDot;
        dotCount++;

        let found = false;
        for (const un of uniqueNormals) {
          const dot = un[0] * faceNormalNorm[0] + un[1] * faceNormalNorm[1] + un[2] * faceNormalNorm[2];
          // normals are flat if they point in the exact same direction
          if (dot > 0.999) {
            found = true;
            break;
          }
        }
        if (!found) {
          uniqueNormals.push(faceNormalNorm);
        }
      }
    }

    const isInner = dotCount > 0 ? (dotSum / dotCount < 0) : false;

    // 3. Classify face type based on triangulation characteristics
    let type: "planar" | "cylindrical" | "curved" = "curved";
    if (uniqueNormals.length === 1) {
      type = "planar";
    } else if (uniqueNormals.length <= 4 && uniqueNormals.length > 1) {
      // Cylindrical/extruded features have grouped normal bands
      type = "cylindrical";
    } else if (uniqueNormals.length > 4) {
      // Or we check standard bounding box ratios / circular projections
      // In small tessellations sometimes a cylinder returns many normals, so let's classify it as cylindrical/curved
      type = "cylindrical";
    }

    return {
      index,
      id: `BRepFace-${index}`,
      type,
      area: parseFloat(totalArea.toFixed(2)),
      center: {
        x: parseFloat(centerX.toFixed(2)),
        y: parseFloat(centerY.toFixed(2)),
        z: parseFloat(centerZ.toFixed(2))
      },
      normal: type === "planar" && uniqueNormals.length > 0 ? {
        x: parseFloat(uniqueNormals[0][0].toFixed(4)),
        y: parseFloat(uniqueNormals[0][1].toFixed(4)),
        z: parseFloat(uniqueNormals[0][2].toFixed(4))
      } : undefined,
      isInner
    };
  });
}

/**
 * Runs an advanced geometric sorting algorithm to dynamically map
 * standard STEP Datum and Tolerance anchors to their actual 3D B-Rep mesh counterparts,
 * resolving parsing order mismatches completely!
 */
export function autoGenerateFaceMapping(
  meshes: any[],
  rawStepText?: string
): Record<string, string> {
  const mapping: Record<string, string> = {};
  if (!meshes || meshes.length === 0) return mapping;

  const classified = classifyBRepFaces(meshes);
  const shellFaceOrder: string[] = [];

  const applyClosedShellFaceOrderMapping = () => {
    if (!rawStepText) return 0;

    const entityStatements = rawStepText.match(/#\d+\s*=\s*[\s\S]*?;/g) || [];
    let faceOrdinal = 0;
    let mappedCount = 0;

    for (const statement of entityStatements) {
      if (!/\bCLOSED_SHELL\b/i.test(statement)) continue;

      const refs = statement.match(/#\d+/g) || [];
      // The first reference is the CLOSED_SHELL entity id. The rest are shell faces in topological order.
      for (const faceId of refs.slice(1)) {
        if (!shellFaceOrder.includes(faceId)) {
          shellFaceOrder.push(faceId);
        }
        if (faceOrdinal < meshes.length) {
          mapping[faceId] = `BRepFace-${faceOrdinal}`;
          mappedCount++;
        }
        faceOrdinal++;
      }
    }

    return mappedCount;
  };

  const findNearestMappedShellFace = (targetId: string): string | undefined => {
    if (mapping[targetId]) return mapping[targetId];

    const targetIndex = shellFaceOrder.indexOf(targetId);
    if (targetIndex === -1) return undefined;

    for (let offset = 1; offset < shellFaceOrder.length; offset++) {
      const previous = shellFaceOrder[targetIndex - offset];
      if (previous && mapping[previous]) return mapping[previous];

      const next = shellFaceOrder[targetIndex + offset];
      if (next && mapping[next]) return mapping[next];
    }

    return undefined;
  };

  const mapDatumLettersFromParsedTargets = () => {
    if (!rawStepText) return;

    const datumTargetByLetter = new Map<string, string>();
    const entityStatements = new Map<string, string>();
    for (const match of rawStepText.matchAll(/#(\d+)\s*=\s*([\s\S]*?);/g)) {
      entityStatements.set(`#${match[1]}`, match[2].replace(/\s+/g, " ").trim());
    }

    const getEntityType = (entityId: string): string => {
      const statement = entityStatements.get(entityId) || "";
      return statement.match(/^([A-Z0-9_]+)/i)?.[1]?.toUpperCase() || "";
    };
    const getEntityRefs = (entityId: string): string[] => entityStatements.get(entityId)?.match(/#\d+/g) || [];
    const isMappableGeometryTarget = (entityId: string): boolean => {
      const type = getEntityType(entityId);
      return /^(ADVANCED_FACE|FACE_SURFACE|FACE_BOUND|EDGE_CURVE|VERTEX_POINT|CARTESIAN_POINT|AXIS2_PLACEMENT_3D|PLANE|CYLINDRICAL_SURFACE|CONICAL_SURFACE|SPHERICAL_SURFACE|TOROIDAL_SURFACE|B_SPLINE_SURFACE)$/i.test(type) ||
        !!mapping[entityId] ||
        !!findNearestMappedShellFace(entityId);
    };
    const getCartesianPoint = (entityId: string): { x: number; y: number; z: number } | null => {
      const statement = entityStatements.get(entityId);
      if (!statement) return null;

      const match = statement.match(/CARTESIAN_POINT\s*\(\s*[^,]*\s*,\s*\(\s*([-+]?(?:\d+\.?\d*|\.\d+)(?:[Ee][-+]?\d+)?)\s*,\s*([-+]?(?:\d+\.?\d*|\.\d+)(?:[Ee][-+]?\d+)?)\s*,\s*([-+]?(?:\d+\.?\d*|\.\d+)(?:[Ee][-+]?\d+)?)\s*\)\s*\)/i);
      if (!match) return null;

      return {
        x: parseFloat(match[1]),
        y: parseFloat(match[2]),
        z: parseFloat(match[3])
      };
    };

    const pointCentroid = (points: { x: number; y: number; z: number }[]) => {
      if (points.length === 0) return null;
      const sum = points.reduce((acc, point) => ({
        x: acc.x + point.x,
        y: acc.y + point.y,
        z: acc.z + point.z
      }), { x: 0, y: 0, z: 0 });

      return {
        x: sum.x / points.length,
        y: sum.y / points.length,
        z: sum.z / points.length
      };
    };

    const entityPointCache = new Map<string, { x: number; y: number; z: number }[]>();
    const getEntityCartesianPoints = (
      entityId: string,
      depth = 8,
      visited = new Set<string>()
    ): { x: number; y: number; z: number }[] => {
      if (depth < 0 || visited.has(entityId)) return [];
      if (entityPointCache.has(entityId)) return entityPointCache.get(entityId)!;

      visited.add(entityId);
      const directPoint = getCartesianPoint(entityId);
      if (directPoint) {
        visited.delete(entityId);
        entityPointCache.set(entityId, [directPoint]);
        return [directPoint];
      }

      const points: { x: number; y: number; z: number }[] = [];
      for (const ref of getEntityRefs(entityId)) {
        points.push(...getEntityCartesianPoints(ref, depth - 1, visited));
      }
      visited.delete(entityId);

      entityPointCache.set(entityId, points);
      return points;
    };

    const squaredDistance = (
      a: { x: number; y: number; z: number },
      b: { x: number; y: number; z: number }
    ) => {
      const dx = a.x - b.x;
      const dy = a.y - b.y;
      const dz = a.z - b.z;
      return dx * dx + dy * dy + dz * dz;
    };

    const selectDatumAnnotationTarget = (annotationId: string, targetIds: string[]) => {
      if (targetIds.length <= 1) return targetIds[0];

      const faceTargets = targetIds.filter((targetId) => /^(ADVANCED_FACE|FACE_SURFACE)\s*\(/i.test(entityStatements.get(targetId) || ""));
      if (faceTargets.length === 1) return faceTargets[0];
      if (faceTargets.length === 0) return targetIds.find((target) => mapping[target]);

      const annotationCenter = pointCentroid(getEntityCartesianPoints(annotationId, 4));
      if (!annotationCenter) return faceTargets.find((target) => mapping[target]);

      const scoredTargets = faceTargets
        .map((targetId, index) => {
          const targetCenter = pointCentroid(getEntityCartesianPoints(targetId, 10));
          return targetCenter
            ? { targetId, index, distance: squaredDistance(annotationCenter, targetCenter) }
            : null;
        })
        .filter((item): item is { targetId: string; index: number; distance: number } => !!item)
        .sort((a, b) => a.distance - b.distance || a.index - b.index);

      return scoredTargets[0]?.targetId || faceTargets.find((target) => mapping[target]);
    };

    const getDatumPresentationIdentifier = (annotationId: string): string | null => {
      const annotationRefs = getEntityRefs(annotationId);
      const curveSetId = annotationRefs[annotationRefs.length - 1];
      if (!curveSetId) return null;

      const curveRefs = getEntityRefs(curveSetId);
      if (curveRefs.length < 7) return null;

      const letterStrokeRefs = curveRefs.slice(3, -3);
      const strokePointCounts = letterStrokeRefs
        .map((ref) => getEntityRefs(ref).length)
        .filter((count) => count > 0);

      const signature = strokePointCounts.join(",");
      const glyphSignatures: Record<string, string> = {
        "9,4": "A",
        "64,35,40": "B",
        "149": "C",
        "49": "J",
        "4,4,2,49,34,24": "B",
        "4,4,2,83": "C",
        "2,4,13,2,9,15": "A",
        "11": "F",
        "87": "G",
        "44,44": "D"
      };

      if (glyphSignatures[signature]) {
        return glyphSignatures[signature];
      }

      const reducedSignature = strokePointCounts.filter((count) => count > 20).join(",");
      if (glyphSignatures[reducedSignature]) {
        return glyphSignatures[reducedSignature];
      }

      if (signature === "39,48" || reducedSignature === "39,48") {
        return "D";
      }

      if (signature === "13") {
        const letterCurve = letterStrokeRefs.find((ref) => getEntityRefs(ref).filter((pointRef) => !!getCartesianPoint(pointRef)).length === 13);
        const points = letterCurve
          ? getEntityRefs(letterCurve).map(getCartesianPoint).filter((point): point is { x: number; y: number; z: number } => !!point)
          : [];

        if (points.length >= 2) {
          const axes: Array<"x" | "y" | "z"> = ["x", "y", "z"];
          const spans = axes.map((axis) => ({
            axis,
            min: Math.min(...points.map((point) => point[axis])),
            max: Math.max(...points.map((point) => point[axis]))
          })).sort((a, b) => (b.max - b.min) - (a.max - a.min));
          const firstSegmentFraction = spans.slice(0, 2).reduce((largest, spanInfo) => {
            const span = Math.max(1e-9, spanInfo.max - spanInfo.min);
            const fraction = Math.abs(points[1][spanInfo.axis] - points[0][spanInfo.axis]) / span;
            return Math.max(largest, fraction);
          }, 0);
          return firstSegmentFraction > 0.7 ? "E" : "H";
        }

        return "E";
      }

      return null;
    };

    const datumFeatureLines = rawStepText.match(/#\d+\s*=\s*(DATUM|DATUM_FEATURE)\s*\(.*?\)/gi) || [];
    for (const line of datumFeatureLines) {
      const letterMatch = line.match(/'([A-Z])'/);
      const targetIdMatch = line.match(/,\s*#(\d+)/);
      if (letterMatch && targetIdMatch) {
        datumTargetByLetter.set(letterMatch[1], `#${targetIdMatch[1]}`);
      }
    }

    const shapeAspectToTargets = new Map<string, string[]>();
    const usageLines = rawStepText.match(/#\d+\s*=\s*GEOMETRIC_ITEM_SPECIFIC_USAGE\s*\([\s\S]*?\);/gi) || [];
    for (const line of usageLines) {
      const match = line.match(/GEOMETRIC_ITEM_SPECIFIC_USAGE\s*\(\s*[^,]*\s*,\s*[^,]*\s*,\s*#(\d+)\s*,\s*#(\d+)\s*,\s*#(\d+)\s*\)/i);
      if (!match) continue;

      const shapeAspectId = `#${match[1]}`;
      const targetId = `#${match[3]}`;
      const targets = shapeAspectToTargets.get(shapeAspectId) || [];
      if (!targets.includes(targetId)) {
        targets.push(targetId);
      }
      shapeAspectToTargets.set(shapeAspectId, targets);
    }

    const annotationToShapeAspects = new Map<string, string[]>();
    const associationLines = rawStepText.match(/#\d+\s*=\s*DRAUGHTING_MODEL_ITEM_ASSOCIATION\s*\([\s\S]*?\);/gi) || [];
    for (const line of associationLines) {
      const match = line.match(/DRAUGHTING_MODEL_ITEM_ASSOCIATION\s*\(\s*[^,]*\s*,\s*[^,]*\s*,\s*#(\d+)\s*,\s*#(\d+)\s*,\s*#(\d+)\s*\)/i);
      if (!match) continue;

      const shapeAspectId = `#${match[1]}`;
      const annotationId = `#${match[3]}`;
      const aspects = annotationToShapeAspects.get(annotationId) || [];
      if (!aspects.includes(shapeAspectId)) {
        aspects.push(shapeAspectId);
      }
      annotationToShapeAspects.set(annotationId, aspects);
    }

    const resolveAnnotationTargets = (annotationId: string): string[] => {
      const resolved: string[] = [];
      const aspects = annotationToShapeAspects.get(annotationId) || [];
      for (const aspect of aspects) {
        const targets = shapeAspectToTargets.get(aspect) || [];
        for (const target of targets) {
          if (!resolved.includes(target)) {
            resolved.push(target);
          }
        }
      }
      return resolved;
    };

    const datumEntityByLetter = new Map<string, string>();
    const datumFeatureByOrdinal = new Map<number, string>();
    const representationTargetsByFeature = new Map<string, string[]>();

    for (const [entityId, statement] of entityStatements.entries()) {
      const datumMatch = statement.match(/^DATUM\s*\(([\s\S]*)\)$/i);
      if (datumMatch) {
        const letter = (datumMatch[1].match(/'([^']*)'/g) || [])
          .map((value) => value.replace(/'/g, "").trim().toUpperCase())
          .reverse()
          .find((value) => /^[A-Z]$/.test(value));
        if (letter) {
          datumEntityByLetter.set(letter, entityId);
        }
      }

      const datumFeatureMatch = statement.match(/^DATUM_FEATURE\s*\(\s*'[^']*?(\d+)'\s*,/i);
      if (datumFeatureMatch) {
        datumFeatureByOrdinal.set(parseInt(datumFeatureMatch[1], 10), entityId);
      }

      if (/^ITEM_IDENTIFIED_REPRESENTATION_USAGE\s*\(/i.test(statement)) {
        const refs = statement.match(/#\d+/g) || [];
        if (refs.length >= 4) {
          const featureId = refs[1];
          const targets = refs.slice(3).filter(isMappableGeometryTarget);
          if (targets.length > 0) {
            representationTargetsByFeature.set(featureId, targets);
          }
        }
      }
    }

    const semanticLetters = Array.from(datumEntityByLetter.keys()).sort((a, b) => a.localeCompare(b));
    for (const [index, letter] of semanticLetters.entries()) {
      const existingTarget = datumTargetByLetter.get(letter);
      if (existingTarget && mapping[existingTarget]) continue;

      const datumEntityId = datumEntityByLetter.get(letter)!;
      const ordinal = index + 1;
      const featureId = datumFeatureByOrdinal.get(ordinal);
      const directTargets = (shapeAspectToTargets.get(datumEntityId) || []).filter(isMappableGeometryTarget);
      const featureTargets = featureId
        ? (representationTargetsByFeature.get(featureId) || shapeAspectToTargets.get(featureId) || [])
        : [];
      const targetId = [...directTargets, ...featureTargets]
        .filter(isMappableGeometryTarget)
        .find((target) => mapping[target] || findNearestMappedShellFace(target));

      if (targetId) {
        datumTargetByLetter.set(letter, targetId);
      }
    }

    const usedPresentationLetters = new Set<string>(datumTargetByLetter.keys());
    const nextDatumIdentifier = () => {
      let code = 65;
      while (usedPresentationLetters.has(String.fromCharCode(code))) {
        code++;
      }
      const identifier = String.fromCharCode(code);
      usedPresentationLetters.add(identifier);
      return identifier;
    };

    const datumAnnotationLines = rawStepText.match(/#\d+\s*=\s*\w+\s*\(\s*'datum'[\s\S]*?\);/gi) || [];
    for (const line of datumAnnotationLines) {
      const annotationMatch = line.match(/#(\d+)\s*=/);
      if (!annotationMatch) continue;

      const annotationId = `#${annotationMatch[1]}`;
      const identifier = getDatumPresentationIdentifier(annotationId);
      if (!identifier) continue;
      if (datumTargetByLetter.has(identifier)) continue;

      const annotationTargets = resolveAnnotationTargets(annotationId);
      const targetId = selectDatumAnnotationTarget(annotationId, annotationTargets);
      if (targetId) {
        datumTargetByLetter.set(identifier, targetId);
      }
    }

    for (const [letter, targetId] of datumTargetByLetter.entries()) {
      const bRepFaceId = mapping[targetId] || findNearestMappedShellFace(targetId);
      if (bRepFaceId) {
        mapping[letter] = bRepFaceId;
      }
    }
  };

  // If raw STEP file is loaded, perform high-grade mathematical physical alignment!
  if (rawStepText) {
    try {
      const shellMappedCount = applyClosedShellFaceOrderMapping();
      const rawEntityStatements = new Map<string, string>();
      for (const match of rawStepText.matchAll(/#(\d+)\s*=\s*([\s\S]*?);/g)) {
        rawEntityStatements.set(`#${match[1]}`, match[2].replace(/\s+/g, " ").trim());
      }

      // 1. Extract raw geometric point registries
      const points = new Map<string, { x: number; y: number; z: number }>();
      const numberPattern = "[-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[Ee][-+]?\\d+)?";
      const pointPattern = new RegExp(`^CARTESIAN_POINT\\s*\\(\\s*[^,]*\\s*,\\s*\\(\\s*(${numberPattern})\\s*,\\s*(${numberPattern})\\s*,\\s*(${numberPattern})\\s*\\)\\s*\\)$`, "i");
      for (const [id, statement] of rawEntityStatements.entries()) {
        const match = statement.match(pointPattern);
        if (match) {
          points.set(id, {
            x: parseFloat(match[1]),
            y: parseFloat(match[2]),
            z: parseFloat(match[3])
          });
        }
      }

      // 2. Extract direction vectors (e.g., normal or axis variables)
      const directions = new Map<string, { x: number; y: number; z: number }>();
      const directionPattern = new RegExp(`^DIRECTION\\s*\\(\\s*[^,]*\\s*,\\s*\\(\\s*(${numberPattern})\\s*,\\s*(${numberPattern})\\s*,\\s*(${numberPattern})\\s*\\)\\s*\\)$`, "i");
      for (const [id, statement] of rawEntityStatements.entries()) {
        const match = statement.match(directionPattern);
        if (match) {
          directions.set(id, {
            x: parseFloat(match[1]),
            y: parseFloat(match[2]),
            z: parseFloat(match[3])
          });
        }
      }

      // 3. Extract Axis Placements
      const placements = new Map<string, { origin: { x: number; y: number; z: number }; axis?: { x: number; y: number; z: number } }>();
      const placementLines = rawStepText.match(/#\d+\s*=\s*AXIS2_PLACEMENT_3D\s*\(.*?\)/gi) || [];
      for (const line of placementLines) {
        const match = line.match(/#(\d+)\s*=\s*AXIS2_PLACEMENT_3D\s*\(\s*[^,]*\s*,\s*#(\d+)\s*,\s*(#\d+|\$)\s*,\s*(#\d+|\$)\s*\)/i);
        if (match) {
          const id = `#${match[1]}`;
          const originId = `#${match[2]}`;
          const axisId = match[3] !== "$" ? match[3] : undefined;
          const origin = points.get(originId);
          if (origin) {
            const axis = axisId ? directions.get(axisId) : undefined;
            placements.set(id, { origin, axis });
          }
        }
      }

      // 4. Extract Planes
      const planes = new Map<string, { origin: { x: number; y: number; z: number }; normal: { x: number; y: number; z: number } }>();
      const planeLines = rawStepText.match(/#\d+\s*=\s*PLANE\s*\(.*?\)/gi) || [];
      for (const line of planeLines) {
        const match = line.match(/#(\d+)\s*=\s*PLANE\s*\(\s*[^,]*\s*,\s*#(\d+)\s*\)/i);
        if (match) {
          const id = `#${match[1]}`;
          const placementId = `#${match[2]}`;
          const placement = placements.get(placementId);
          const point = points.get(placementId);
          const origin = placement ? placement.origin : (point || { x: 0, y: 0, z: 0 });
          const normal = (placement && placement.axis) ? placement.axis : { x: 0, y: 0, z: 1 };
          planes.set(id, { origin, normal });
        }
      }

      // 5. Extract Cylinders
      const cylindricalSurfaces = new Map<string, { origin: { x: number; y: number; z: number }; axis: { x: number; y: number; z: number }; radius: number }>();
      const cylinderLines = rawStepText.match(/#\d+\s*=\s*CYLINDRICAL_SURFACE\s*\(.*?\)/gi) || [];
      for (const line of cylinderLines) {
        const match = line.match(/#(\d+)\s*=\s*CYLINDRICAL_SURFACE\s*\(\s*[^,]*\s*,\s*#(\d+)\s*,\s*(-?\d+\.?\d*e?-?\d*)\s*\)/i);
        if (match) {
          const id = `#${match[1]}`;
          const placementId = `#${match[2]}`;
          const radius = parseFloat(match[3]);
          const placement = placements.get(placementId);
          const origin = placement ? placement.origin : { x: 0, y: 0, z: 0 };
          const axis = (placement && placement.axis) ? placement.axis : { x: 0, y: 0, z: 1 };
          cylindricalSurfaces.set(id, { origin, axis, radius });
        }
      }

      // 6. Map ADVANCED_FACE to underlying analytical surfaces
      interface StepFace {
        id: string;
        surfaceId: string;
        surfaceType: "plane" | "cylinder";
      }
      const stepFaces: StepFace[] = [];
      const faceLines = rawStepText.match(/#\d+\s*=\s*ADVANCED_FACE\s*\(.*?\)/gi) || [];
      for (const line of faceLines) {
        const match = line.match(/#(\d+)\s*=\s*ADVANCED_FACE\s*\((.*)\)/i);
        if (match) {
          const id = `#${match[1]}`;
          const params = match[2];
          const refs = params.match(/#\d+/g) || [];
          for (const ref of refs) {
            if (planes.has(ref)) {
              stepFaces.push({ id, surfaceId: ref, surfaceType: "plane" });
              break;
            } else if (cylindricalSurfaces.has(ref)) {
              stepFaces.push({ id, surfaceId: ref, surfaceType: "cylinder" });
              break;
            }
          }
        }
      }

      const getEntityRefs = (entityId: string): string[] => rawEntityStatements.get(entityId)?.match(/#\d+/g) || [];
      const collectEntityPoints = (entityId: string, visited = new Set<string>()): { x: number; y: number; z: number }[] => {
        if (visited.has(entityId)) return [];
        visited.add(entityId);

        const point = points.get(entityId);
        if (point) return [point];

        return getEntityRefs(entityId).flatMap((ref) => collectEntityPoints(ref, visited));
      };

      const getBounds = (pts: { x: number; y: number; z: number }[]) => {
        if (pts.length === 0) return null;

        const xs = pts.map((pt) => pt.x);
        const ys = pts.map((pt) => pt.y);
        const zs = pts.map((pt) => pt.z);
        const min = { x: Math.min(...xs), y: Math.min(...ys), z: Math.min(...zs) };
        const max = { x: Math.max(...xs), y: Math.max(...ys), z: Math.max(...zs) };
        return {
          min,
          max,
          center: {
            x: (min.x + max.x) / 2,
            y: (min.y + max.y) / 2,
            z: (min.z + max.z) / 2
          },
          size: {
            x: max.x - min.x,
            y: max.y - min.y,
            z: max.z - min.z
          }
        };
      };

      const distance = (a: { x: number; y: number; z: number }, b: { x: number; y: number; z: number }) => {
        const dx = a.x - b.x;
        const dy = a.y - b.y;
        const dz = a.z - b.z;
        return Math.sqrt(dx * dx + dy * dy + dz * dz);
      };

      const remapFacesByGeometry = () => {
        const stepFaceBounds = faceLines.flatMap((line) => {
          const match = line.match(/#(\d+)\s*=\s*ADVANCED_FACE/i);
          if (!match) return [];

          const id = `#${match[1]}`;
          const bounds = getBounds(collectEntityPoints(id));
          return bounds ? [{ id, bounds }] : [];
        });

        const meshBounds = meshes.flatMap((mesh, index) => {
          const positions = mesh.positions || [];
          const pts: { x: number; y: number; z: number }[] = [];
          for (let i = 0; i < positions.length; i += 3) {
            pts.push({ x: positions[i], y: positions[i + 1], z: positions[i + 2] });
          }

          const bounds = getBounds(pts);
          return bounds ? [{ id: `BRepFace-${index}`, bounds }] : [];
        });

        let remapped = 0;
        for (const stepFace of stepFaceBounds) {
          let bestMeshId = "";
          let bestScore = Infinity;

          for (const mesh of meshBounds) {
            const centerScore = distance(stepFace.bounds.center, mesh.bounds.center);
            const sizeScore = distance(stepFace.bounds.size, mesh.bounds.size) * 0.35;
            const score = centerScore + sizeScore;
            if (score < bestScore) {
              bestScore = score;
              bestMeshId = mesh.id;
            }
          }

          const faceDiagonal = Math.max(1, distance(stepFace.bounds.min, stepFace.bounds.max));
          if (bestMeshId && bestScore <= faceDiagonal * 0.2 && !mapping[stepFace.id]) {
            mapping[stepFace.id] = bestMeshId;
            remapped++;
          }
        }

        return remapped;
      };

      remapFacesByGeometry();

      // Helper helper to pull evenly distributed sampling vertices
      const getSubsampledVertices = (mesh: any, maxCount: number = 25): { x: number; y: number; z: number }[] => {
        const positions = mesh.positions || [];
        const total = positions.length / 3;
        if (total === 0) return [];
        const interval = Math.max(1, Math.floor(total / maxCount));
        const res: { x: number; y: number; z: number }[] = [];
        for (let i = 0; i < total; i += interval) {
          res.push({
            x: positions[i * 3],
            y: positions[i * 3 + 1],
            z: positions[i * 3 + 2]
          });
          if (res.length >= maxCount) break;
        }
        return res;
      };

      // 7. Mathematically rank and assign each B-Rep Face mesh to its closest STEP Face entity
      for (const bRepFace of classified) {
        const mesh = meshes[bRepFace.index];
        const sampledVerts = getSubsampledVertices(mesh, 25);
        if (sampledVerts.length === 0) continue;

        let bestStepId = "";
        let minDeviation = Infinity;

        for (const sFace of stepFaces) {
          if (sFace.surfaceType === "plane") {
            const plane = planes.get(sFace.surfaceId)!;
            let sumDist = 0;
            for (const pt of sampledVerts) {
              const dx = pt.x - plane.origin.x;
              const dy = pt.y - plane.origin.y;
              const dz = pt.z - plane.origin.z;
              const d = Math.abs(dx * plane.normal.x + dy * plane.normal.y + dz * plane.normal.z);
              sumDist += d;
            }
            const avgDev = sumDist / sampledVerts.length;
            if (avgDev < minDeviation) {
              minDeviation = avgDev;
              bestStepId = sFace.id;
            }
          } else if (sFace.surfaceType === "cylinder") {
            const cyl = cylindricalSurfaces.get(sFace.surfaceId)!;
            const ax = cyl.axis.x;
            const ay = cyl.axis.y;
            const az = cyl.axis.z;
            const len = Math.sqrt(ax * ax + ay * ay + az * az);
            const nax = len > 1e-6 ? ax / len : 0;
            const nay = len > 1e-6 ? ay / len : 0;
            const naz = len > 1e-6 ? az / len : 1;

            let sumRadialDev = 0;
            for (const pt of sampledVerts) {
              const dx = pt.x - cyl.origin.x;
              const dy = pt.y - cyl.origin.y;
              const dz = pt.z - cyl.origin.z;
              const proj = dx * nax + dy * nay + dz * naz;
              const rx = dx - proj * nax;
              const ry = dy - proj * nay;
              const rz = dz - proj * naz;
              const rDist = Math.sqrt(rx * rx + ry * ry + rz * rz);
              sumRadialDev += Math.abs(rDist - cyl.radius);
            }
            const avgDev = sumRadialDev / sampledVerts.length;
            if (avgDev < minDeviation) {
              minDeviation = avgDev;
              bestStepId = sFace.id;
            }
          }
        }

        if (bestStepId && minDeviation < 1.5 && !mapping[bestStepId]) {
          mapping[bestStepId] = bRepFace.id;
        }
      }

      // 8. Correlate direct single-character Datum identifiers (A, B, C) to mapped targets.
      mapDatumLettersFromParsedTargets();

      if (Object.keys(mapping).length > 2 || shellMappedCount > 0) {
        return mapping;
      }
    } catch (e) {
      console.warn("Raw STEP analytical geometry mapper encountered exception, falling back to heuristics:", e);
    }
  }

  return mapping;
}
